where del_flag = 0

    and (lead_no like concat('%', #{keyword}, '%')
    or name like concat('%', #{keyword}, '%')
    or company like concat('%', #{keyword}, '%')
    or contact like concat('%', #{keyword}, '%')
    or phone like concat('%', #{keyword}, '%'))


    and status = #{status}


    and source = #{source}


    and level = #{level}

